{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group and rules lack descriptions",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group and its inline rules have no descriptions, making their intended security purpose difficult to audit and maintain."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Unrestricted ingress from the internet",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The ingress rule uses protocol -1 with 0.0.0.0/0, exposing every port and protocol to all IPv4 addresses."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "SSH is exposed to the internet",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The all-protocol ingress rule implicitly exposes TCP port 22 to 0.0.0.0/0, permitting SSH connection attempts from any IPv4 address."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "RDP is exposed to the internet",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The all-protocol ingress rule implicitly exposes TCP port 3389 to 0.0.0.0/0, permitting RDP connection attempts from any IPv4 address."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "HTTP is exposed to the internet",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The all-protocol ingress rule implicitly exposes unencrypted HTTP on port 80 to every IPv4 address."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Unrestricted outbound traffic",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The egress rule permits all protocols and ports to 0.0.0.0/0, allowing unrestricted outbound communication and increasing data-exfiltration risk."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name        = \"allow-all-lb\"\n  description = \"Security group for the load balancer\"\n  vpc_id      = data.aws_vpc.main.id\n}\n",
  "fix_summary": "Added a security group description and removed the unrestricted ingress and egress rules. With no approved ports or destinations defined in this file, the hardened configuration denies traffic by default."
}
